def maxProduct(n, a):
    max_product = 0
    for i in range(n):
        if a[i] == 1:
            max_product = max(max_product, a[i] * a[i])
    return max_product

def main():
    n = int(input())
    a = list(map(int, input().split()))
    max_product = maxProduct(n, a)
    print(max_product)

if __name__ == "__main__":
    main()

