def substring_min_extra(s, dictionary):
    if len(s) == 0:
        return 0

    # Initialize the extra characters
    extra_chars = [0] * len(s)

    # Initialize the substring count
    substrings = 0

    # Iterate over the characters in s
    for i in range(len(s)):
        # If the character is in dictionary, increment the substring count
        if s[i] in dictionary:
            substrings += 1

        # If the character is not in dictionary, increment the extra characters
        else:
            extra_chars[i] += 1

    # Return the minimum number of extra characters
    return min(substrings, extra_chars[len(s) - 1])

