def concatenate_strings(x, y, z):
    if x == 0:
        return ""
    elif y == 0:
        return ""
    elif z == 0:
        return ""
    elif x == y:
        return x + y + z
    elif x == z:
        return x + z + y
    elif y == z:
        return y + z + x
    else:
        return concatenate_strings(x - 1, y, z) + concatenate_strings(x, y - 1, z) + concatenate_strings(x, z - 1, y)

def maxJumps(nums, target):
    n = len(nums)
    max_jumps = 0

    for i in range(n):
        if i == 0:
            max_jumps += 1
        else:
            if nums[i] - nums[i-1] == target:
                max_jumps += 1
            else:
                max_jumps += max(maxJumps(nums, target - nums[i-1]), maxJumps(nums, target - nums[i]))

    return max_jumps

def countCompleteSubarrays(nums):
    # Initialize a dictionary to store the number of complete subarrays
    complete_subarrays = {}

    # Iterate through the array
    for i in range(len(nums)):
        # Check if the current subarray is complete
        if len(set(nums[i:])) == len(nums[i:]):
            # If it is, increment the count
            complete_subarrays[i] = complete_subarrays.get(i, 0) + 1

    # Return the number of complete subarrays
    return complete_subarrays.get(len(nums), 0)

def maxDistance(mainTank, additionalTank):
    if mainTank == 0:
        return 0
    if additionalTank == 0:
        return mainTank

    fuel_in_main_tank = mainTank
    fuel_in_additional_tank = additionalTank

    if fuel_in_main_tank < fuel_in_additional_tank:
        fuel_in_main_tank = fuel_in_additional_tank

    distance_traveled = fuel_in_main_tank * 10

    while fuel_in_main_tank > 0:
        fuel_in_main_tank -= 5
        distance_traveled += fuel_in_main_tank * 10

    return distance_traveled

