def count_ways(n, x):
    # Initialize the count
    count = 0

    # Iterate over all possible values of x
    for x_val in range(1, x + 1):
        # Iterate over all possible values of n
        for n_val in range(1, n + 1):
            # Check if n_val^x is a valid solution
            if n_val ** x_val == n:
                count += 1

    # Return the count modulo 10^9 + 7
    return count % (10**9 + 7)

def partition_string(s):
    # Check if the string is empty
    if not s:
        return -1

    # Check if the string is a power of 5
    if not s.startswith('0b'):
        return -1

    # Convert the string to binary
    binary_string = bin(int(s, 2))[2:]

    # Find the minimum number of substrings
    min_substrings = len(binary_string)

    # Check if the binary string is a power of 5
    for i in range(len(binary_string)):
        if int(binary_string[i:i+2], 2) == int(binary_string[i:i+2], 2) ** 5:
            min_substrings = min(min_substrings, i+1)

    return min_substrings

