def createGroups(usageLimits):
    groups = []
    for i in range(len(usageLimits)):
        if usageLimits[i] > 0:
            if i > 0:
                groups.append(usageLimits[i-1])
            groups.append(usageLimits[i])
            if i < len(usageLimits)-1:
                groups.append(usageLimits[i+1])
    return max(groups)

def equalize(nums):
    n = len(nums)
    for i in range(n):
        for j in range(i, n):
            if nums[i] == nums[j]:
                nums[i] = nums[j]
                nums[(i - 1 + n) % n] = nums[(i + 1) % n]
                break
    return min(n, len(nums))

