def find_pairs_with_distance(coordinates, k):
    # Initialize a set to store the pairs
    pairs = set()

    # Iterate through each pair (i, j)
    for i in range(len(coordinates)):
        for j in range(i+1, len(coordinates)):
            # Calculate the distance between i and j
            distance = coordinates[i][0] ^ coordinates[j][0] + coordinates[i][1] ^ coordinates[j][1]

            # Check if the distance is equal to k
            if distance == k:
                pairs.add((i, j))

    return len(pairs)

def purchase_balance(purchase_amount):
    # Calculate the nearest multiple of 10 to the purchase amount
    nearest_multiple = 10
    for i in range(1, int(purchase_amount / nearest_multiple)):
        if purchase_amount % nearest_multiple == 0:
            nearest_multiple = nearest_multiple * 10

    # Calculate the account balance
    account_balance = purchase_amount - nearest_multiple
    return account_balance

