        for j in range(len(offers)):
            if i == 0 or j == 0:
                continue
            if offers[j][0] <= i <= offers[j][1] and offers[j][2] <= i <= offers[j][2]:
                max_gold = max(max_gold, offers[j][2])
    return max_gold

def count_symmetric_numbers(low, high):
