    count = 0

    # Iterate through the range [low, high]
    for i in range(low, high + 1):
        # Check if the sum of the first n digits of i is equal to the sum of the last n digits of i
        if sum(i[0:n] for n in range(1, len(i) + 1)) == sum(i[-n:] for n in range(1, len(i) + 1)):
            count += 1

