    min_diff = float('inf')
    for i in range(len(nums)):
        if i >= x:
            continue
        for j in range(i+1, len(nums)):
            if abs(nums[i] - nums[j]) >= x:
                if abs(nums[i] - nums[j]) < min_diff:
                    min_diff = abs(nums[i] - nums[j])
    return min_diff

