def product_matrix(grid):
    n, m = len(grid), len(grid[0])
    p = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            p[i][j] = grid[i][j] * (grid[i][j] % 12345) % 12345
    return p

def flip_strings(s1, s2, x):
    if len(s1) != len(s2):
        return -1

    # Initialize the result
    result = 0

    # Choose two indices i and j, and flip both s1[i] and s1[j]
    for i in range(len(s1)):
        for j in range(i+1, len(s1)):
            if s1[i] == s1[j]:
                result += x
                break

    # Choose an index i such that i < len(s1) - 1 and flip both s1[i] and s1[i + 1]
    for i in range(len(s1)):
        if i < len(s1) - 1:
            for j in range(i+1, len(s1)):
                if s1[i] == s1[j]:
                    result += 1
                    break

    return result

def countIntersections(nums):
    intersections = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i][0] <= nums[j][1] <= nums[i][1]:
                intersections += 1
    return intersections

def minOperations(nums, k):
    # Initialize a dictionary to store the operations
    operations = {}

    # Initialize the count of operations
    count = 0

    # Iterate through the array
    for i in range(len(nums)):
        # If the current element is k, increment the count
        if nums[i] == k:
            count += 1

        # If the current element is not k, increment the count
        else:
            count += operations.get(nums[i], 0)

        # If the count is greater than k, remove the last element and add it to the collection
        if count > k:
            nums.pop()
            count -= 1

            # If the count is less than k, add the last element to the collection
            if count < k:
                nums.append(nums.pop())
                count += 1

    # Return the minimum number of operations
    return min(count, k)

def right_shift(nums):
    n = len(nums)
    if n == 0:
        return -1

    for i in range(n):
        nums[i] = nums[i] - 1

    for i in range(n-1, -1, -1):
        nums[i] = nums[i] + 1

    return n

