        if i == 0:
            max_sum = nums[i]
        else:
            max_sum = max(max_sum, nums[i] * nums[i - 1])
    return max_sum

def maxOddBinary(s):
    # Convert the string to binary
    binary = bin(int(s, 2))[2:]

    # Find the maximum odd number from the binary string
    max_odd_number = 0
    for i in range(len(binary)):
        if binary[i] == '1':
            max_odd_number = max(max_odd_number, int(binary[i:i+2], 2))

    # Return the maximum odd binary number
    return str(max_odd_number)

def maxSubarrayScore(nums):
    def helper(nums, l, r):
        if l >= r:
            return 0

        # Check if we can split the array into subarrays
        if r - l + 1 > 1:
            return helper(nums, l, r - 1) + helper(nums, l + 1, r)

        # If we can split, return the score of the subarray
        return helper(nums, l, r)

    return helper(nums, 0, len(nums))
def helper(nums, l, r):
    if l >= r:
        return 0

    # Check if we can split the array into subarrays
    if r - l + 1 > 1:
        return helper(nums, l, r - 1) + helper(nums, l + 1, r)

    # If we can split, return the score of the subarray
    return helper(nums, l, r)

def minLength(nums):
