        return 0

    # Initialize a dictionary to store the count of each subset
    count = {}

    # Initialize the sum of each subset
    sum_of_subsets = [0] * (r - l + 1)

    # Iterate over the array
    for i in range(l, r + 1):
        # Initialize the sum of the current subset
        sum_of_subsets[i] = 0

        # Iterate over the elements in the current subset
        for j in range(i, r + 1):
            # If the current subset's sum is within the range [l, r], increment the count
            if sum_of_subsets[j] >= l and sum_of_subsets[j] <= r:
                count[j] = count.get(j, 0) + 1

        # Update the sum of the current subset
        sum_of_subsets[i] = sum_of_subsets[i] + nums[i]

    # Return the count of the subsets
    return count[r]

