def find_cookie_square(grid):
    # Initialize variables
    rows, cols = len(grid), len(grid[0])
    cookie_square = None

    # Initialize a dictionary to store the cookies
    cookies = {}

    # Iterate through the grid
    for i in range(rows):
        for j in range(cols):
            # Check if the cookie is on the square
            if grid[i][j] == '#':
                # If the cookie is on the square, update the cookie_square
                if cookie_square is None:
                    cookie_square = (i, j)
                else:
                    # If the cookie is not on the square, update the cookies
                    if cookie_square not in cookies:
                        cookies[cookie_square] = 1
                    else:
                        cookies[cookie_square] += 1

    # Return the cookie_square
    return cookie_square

