def max_weight_edges(N, D):
    edges = []
    for i in range(N):
        for j in range(i+1, N):
            edges.append((i, j, D[i, j]))

    edges.sort(key=lambda x: x[2])

    max_weight = 0
    for i in range(N):
        for j in range(i+1, N):
            if edges[i][0] == edges[j][0] and edges[i][1] == edges[j][1]:
                weight = edges[i][2] + edges[j][2]
                if weight > max_weight:
                    max_weight = weight

    return max_weight

def find_triples(A):
    # Initialize the count of triples
    count = 0

    # Iterate through all possible pairs (i,j)
    for i in range(1, len(A) + 1):
        for j in range(i, len(A) + 1):
            # Check if A_i = A_j
            if A[i] == A[j]:
                # If A_i = A_j, then A_i \neq A_j
                if A[i] != A[j]:
                    # Increment the count of triples
                    count += 1

    # Return the count of triples
    return count

