def max_size_pyramid_sequence(A):
    # Initialize the maximum size of the pyramid sequence
    max_size = 0

    # Iterate over all possible operations
    for operation in ['decrease', 'remove', 'decrease_first', 'remove_first', 'decrease_last', 'remove_last']:
        # Check if the operation is valid
        if operation in ['decrease', 'remove', 'decrease_first', 'remove_first', 'decrease_last', 'remove_last']:
            # Check if the operation is possible
            if operation == 'decrease' and A[0] > 1:
                # If the operation is possible, increase the size of the pyramid sequence
                max_size = max(max_size, A[0] - 1)
            elif operation == 'remove' and A[0] == 1:
                # If the operation is possible, decrease the size of the pyramid sequence
                max_size = max(max_size, A[0] - 1)
            elif operation == 'decrease_first' and A[0] > 1:
                # If the operation is possible, decrease the size of the pyramid sequence
                max_size = max(max_size, A[0] - 1)
            elif operation == 'remove_first' and A[0] == 1:
                # If the operation is possible, decrease the size of the pyramid sequence
                max_size = max(max_size, A[0] - 1)
            elif operation == 'decrease_last' and A[0] > 1:
                # If the operation is possible, decrease the size of the pyramid sequence
                max_size = max(max_size, A[0] - 1)
            elif operation == 'remove_last' and A[0] == 1:
                # If the operation is possible, decrease the size of the pyramid sequence
                max_size = max(max_size, A[0] - 1)

    # Return the maximum size of the pyramid sequence
    return max_size

