    if not all(point == point[0] for point in points):
        return False

    # Check if all chords are distinct
    if not all(chord == chord[0] for chord in chords):
        return False

    # Check if all chords intersect
    intersection = False
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            if points[i] == points[j] and chords[i] == chords[j]:
                intersection = True
                break
    return intersection

