        if nums[i] == nums[i+1]:
            count += 1
    return count

def median_of_k(nums, k):
    if k == 0:
        return 0
    if k == 1:
        return nums[0]
    if k % 2 == 0:
        return (nums[k // 2 - 1] + nums[k // 2]) / 2
    else:
        return (nums[k // 2] + nums[k // 2 - 1]) / 2

def maxDistance(nums):
    prime_nums = [num for num in nums if isPrime(num)]
    return max(abs(num - prime_num) for num in prime_nums)

def isPrime(num):
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def encrypt(nums):
    encrypted_nums = []
    for num in nums:
        encrypted_nums.append(max(num, key=num))
    return sum(encrypted_nums)
nums = [1,2,3]
print(encrypt(nums))  # Output: 6

def mark_array(nums, queries):
    n = len(nums)
    m = len(queries)

    # Initialize the answer array
    answer = [0] * m

    # Mark all elements
    for i in range(n):
        for j in range(m):
            if nums[i] == queries[j][0]:
                answer[j] = nums[i]
                break

    return answer

def min_cost(s):
    cost = {}
    for i in range(len(s)):
        if s[i] == '?':
            cost[i] = 0
        else:
            cost[i] = s[i] == '?' and cost.get(i-1, 0) + 1 or cost.get(i-1, 0)
    return min(cost.values())

def powerOfSubsequence(nums, k):
    if k == 0:
        return 0

    power = 0
    for i in range(len(nums)):
        if nums[i] == 0:
            continue
        power += 1
        for j in range(i, len(nums)):
            if nums[j] == 0:
                continue
            power += 1
    return power

def score(s):
    score = 0
    for i in range(len(s)):
        score += abs(ord(s[i]) - ord(s[i+1]))
    return score

def countSubarrays(nums):
    count = 0
    for i in range(len(nums)):
        if i == 0 or i == len(nums) - 1:
            count += 1
        else:
            if nums[i] == nums[i - 1]:
                count += 1
    return count

def count_special_characters(word):
    count = 0
    for char in word:
        if char.isalpha() and char.islower() and char.isupper():
            count += 1
    return count

def add_to_nums(nums1, nums2):
    nums1.sort()
    nums2.sort()

    x = 0

    for i in range(len(nums1)):
        if nums1[i] > nums2[i]:
            nums1[i] += x
        else:
            nums2[i] += x

    return x

def find_min_nums(n, x):
    nums = [x]
    for i in range(n - 1):
        nums.append(nums[-1] & nums[i + 1])
    return min(nums)

def median(nums):
    # Sort the array
    nums.sort()

    # Get the median
    n = len(nums)
    if n % 2 == 0:
        return (nums[n // 2] + nums[n // 2 - 1]) / 2
    else:
        return nums[n // 2]

def minLengthAnagram(s):
    # Convert the string to lowercase
    s = s.lower()

    # Create a dictionary to store the anagrams
    anagrams = {}

    # Iterate over each character in the string
    for char in s:
        # Check if the character is already in the dictionary
        if char in anagrams:
            # If it is, return the length of the anagram
            return len(anagrams[char])
        # If it is not, add it to the dictionary
        anagrams[char] = 1

    # If no anagrams are found, return the length of the string
    return len(s)

def canChangeColor(grid):
    for i in range(3):
        for j in range(3):
            if grid[i][j] == 'B':
                if grid[i][j] == 'W':
                    grid[i][j] = 'B'
                else:
                    grid[i][j] = 'W'
    return True

def count_right_triangles(grid):
    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == 1:
                count += 1
    return count

def count_stable_binary_arrays(zero, one, limit):
    # Initialize a dictionary to store the number of stable binary arrays
    stable_binary_arrays = {}

    # Iterate over all possible values of zero and one
    for i in range(zero, one + 1):
        # Initialize a list to store the binary arrays
        binary_arrays = []

        # Iterate over all possible values of limit
        for j in range(limit):
            # Check if the binary array is stable
            if (i, j) in stable_binary_arrays:
                # Increment the count of stable binary arrays
                stable_binary_arrays[(i, j)] += 1
            else:
                # If the binary array is not stable, add it to the list
                binary_arrays.append((i, j))

        # If the list is empty, add the binary array to the dictionary
        if binary_arrays:
            stable_binary_arrays[(i, j)] = len(binary_arrays)

    # Return the total number of stable binary arrays
    return stable_binary_arrays[zero, one] % (10**9 + 7)

def permutation_difference(s, t):
    # Check if s and t are valid strings
    if not s or not t:
        return 0

    # Calculate the permutation difference
    diff = 0
    for i in range(len(s)):
        if s[i] != t[i]:
            diff += abs(i - t[i])
    return diff
print(permutation_difference("abc", "bac"))  # Output: 2
print(permutation_difference("abcde", "edbac"))  # Output: 12

def isSpecialArray(nums):
    # Check if the array is empty
    if not nums:
        return True

    # Check if the array is a single number
    if len(nums) == 1:
        return True

    # Check if the array is a single pair of numbers
    for i in range(len(nums) - 1):
        for j in range(i + 1, len(nums)):
            if nums[i] != nums[j] or nums[i] % 2 != nums[j] % 2:
                return False

    return True

def digit_diff(nums):
    total_diff = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            diff = nums[i] - nums[j]
            total_diff += diff
    return total_diff

def staircase_count(k):
    staircase_count = 0
    for i in range(1, k+1):
        if i == 0:
            staircase_count += 1
        else:
            staircase_count += staircase_count(i)
    return staircase_count

def generate_good_pairs(nums1, nums2, k):
    good_pairs = []
    for i in range(len(nums1)):
        for j in range(len(nums2)):
            if nums1[i] % nums2[j] * k == 0:
                good_pairs.append((i, j))
    return len(good_pairs)

def bitwiseXOR(nums):
    result = 0
    for num in nums:
        if num == nums[0]:
            result ^= 1
        else:
            result ^= num
    return result

